package cleanvisuals.features.presets;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;
import cleanvisuals.features.backgrounds.ImageFit;

/**
 * Everything that describes how one region is styled.
 * <p>
 * Deliberately a plain typed model rather than a bag of config keys. Presets outlive the
 * settings that produced them, and a rename or restructure of the config surface should not
 * silently invalidate every saved preset on disk.
 * <p>
 * Mutable with a no-args constructor because Gson deserialises into it.
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class RegionStyle
{
	/**
	 * Absolute path to the image. Normally inside the plugin's assets directory, since images
	 * are copied there on import so a preset does not depend on where the file came from.
	 */
	private String imagePath = "";

	private ImageFit fit = ImageFit.FILL;
	private int zoomPercent = 100;
	private int focalXPercent = 50;
	private int focalYPercent = 50;

	private int hueShiftDegrees = 0;
	private int saturationPercent = 100;
	private boolean grayscale = false;

	private int imageOpacity = 100;
	private int widgetTransparency = 100;

	/**
	 * Fixed-mode only: pixels of the game's original backing left showing around the image.
	 */
}

